python3 -c "
import json

with open('/app/resources/treasury_bulletin_1956_03.json') as f:
    data = json.load(f)

# Let's try to find any content that might have exchange rate info
def search_for_numbers(obj, path=''):
    results = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            results.extend(search_for_numbers(v, f'{path}.{k}'))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            results.extend(search_for_numbers(v, f'{path}[{i}]'))
    elif isinstance(obj, (int, float)):
        if 0 < obj < 100:  # likely exchange rate values
            results.append((path, obj))
    return results

results = search_for_numbers(data)
for r in results[:20]:
    print(r)
"
